function scan(preview=false){
  page('scan');
  el.innerHTML=status('mint')+`<div class="scan"><div class="scan-content"><div class="scan-aura"><div class="scan-logo"><img class="figma-thinking-gif" src="/star-animation.gif" alt="" width="205" height="205" decoding="async"></div></div><div class="scan-text"><h2>Ik analyseer nu je lijstje</h2><p id="scan-progress" role="status" aria-live="polite" aria-atomic="true">${scanMessages[0]}</p></div></div></div>`;
  if(preview)return;
  let step=0;
  S.scanProgressTimer=setInterval(()=>{
    if(S.page!=='scan')return;
    step++;
    const text=q('#scan-progress');
    if(step<scanMessages.length && text){
      text.textContent=scanMessages[step];
      text.classList.remove('scan-progress-enter');
      void text.offsetWidth;
      text.classList.add('scan-progress-enter');
    }
    if(step>=scanMessages.length-1){clearInterval(S.scanProgressTimer);S.scanProgressTimer=null}
  },3000);
  S.timer=setTimeout(()=>{if(S.page==='scan')compare(0,true)},10000);
}
function offer(p,variant,i){const isAlt=variant==='alt',chosenFlag=S.choices[i]===variant,other=S.choices[i]!==null&&!chosenFlag;return `<article class="offer-card ${isAlt?'alt':'orig'} ${chosenFlag?'selected':''} ${other?'dimmed':''}" data-kind="${variant}"><div class="offer-head ${isAlt?'alternative':'current'}">${isAlt?star(20):ico('cart',18)}<span>${isAlt?'Evenwichtig alternatief':'Dit product behouden'}</span>${chosenFlag?`<span class="selected-chip">${ico('success',12)} Gekozen</span>`:''}</div><div class="offer-content"><div class="offer-photo-wrap"><span class="snowflake">${ico('frozen',24)}</span><img class="offer-photo" src="${p.img}" alt="${esc(p.name)}"><img class="choice-nutri-score" src="/nutri-score-${String(p.grade||'').toUpperCase()}.svg" width="60" height="34" alt="Nutri-Score ${esc(p.grade)}"></div><div class="offer-main"><div class="offer-topline"><div class="offer-title">${esc(p.name)}</div><button aria-label="Favoriet" class="offer-heart" data-action="heart">${ico('heart',22)}</button></div><div class="offer-deal"><div class="offer-deal-line"><span>${esc(p.promo)}</span><span>€ 6,88/kg</span></div><a href="#" onclick="return false">Combineer naar keuze</a></div><div class="offer-price"><strong>${p.price.split(',')[0]}<sup>${p.price.split(',')[1]}</sup></strong><span>/st.</span><small>${p.unit}</small></div></div></div></article>`}
