const prefersReducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function swipeWidth(zone){return Math.max(280,zone?.clientWidth||window.innerWidth||360)}
function swipePose(x,width){
  const p=Math.min(1,Math.abs(x)/width);
  const angle=Math.max(-4.8,Math.min(4.8,x/width*4.8));
  const scale=1-p*.033;
  return {transform:`translate3d(${x}px,0,0) rotate(${angle}deg) scale(${scale})`,opacity:String(1-p*.12)};
}
function setSwipePose(node,x,width){if(!node)return;const p=swipePose(x,width);node.style.transform=p.transform;node.style.opacity=p.opacity;}
function clearSwipePose(node){if(!node)return;node.style.removeProperty('transition');node.style.removeProperty('transform');node.style.removeProperty('opacity');node.style.removeProperty('filter');}
function swipePreview(to){
  const zone=q('#swipeZone');if(!zone)return null;
  let preview=zone.querySelector('.swipe-preview');
  if(preview&&Number(preview.dataset.index)===to)return preview;
  preview?.remove();
  preview=document.createElement('div');
  preview.className='cmp-carousel swipe-preview';
  preview.dataset.index=String(to);
  preview.setAttribute('aria-hidden','true');
  preview.innerHTML=pair(to);
  zone.appendChild(preview);
  return preview;
}
function cleanSwipe(board,preview){
  if(board){board.getAnimations().forEach(a=>a.cancel());clearSwipePose(board)}
  if(preview){preview.getAnimations().forEach(a=>a.cancel());preview.remove()}
  q('#swipeZone')?.classList.remove('swipe-active');
}
function keepPassedProducts(from,to){
  if(to<=from)return;
  for(let i=from;i<to;i++){
    if(S.choices[i]===null)S.choices[i]='orig';
  }
}
async function navigate(to,gesture=null){
  if(S.page!=='compare'||S.busy||S.sheet||to===S.index||to<0||to>=products.length)return;
  const zone=q('#swipeZone'),board=q('#carousel');
  if(!zone||!board)return;
  S.busy=true;
  const oldIndex=S.index;
  const width=swipeWidth(zone);
  const sign=to>oldIndex?1:-1; // next slides in from the right, previous from the left
  const dragged=!!gesture;
  const start=dragged?Math.max(-width*.94,Math.min(width*.94,gesture.dx||0)):0;
  const preview=swipePreview(to);
  if(!preview){S.busy=false;return}
  board.getAnimations().forEach(a=>a.cancel());
  clearSwipePose(board);
  clearSwipePose(preview);
  const from=swipePose(start,width);
  const fromPreview=swipePose(sign*width+start,width);
  const exit=swipePose(-sign*width*1.08,width);
  const speed=dragged?Math.min(1,Math.abs(gesture.velocity||0)):0;
  const travelRemaining=Math.max(.28,1-Math.abs(start)/width);
  const duration=prefersReducedMotion.matches?0:Math.max(260,Math.round((dragged?425:490)*travelRemaining-speed*65));
  const anims=[];
  try{
    zone.classList.add('swipe-active');
    if(duration){
      // Use the real drag positions as animation origins. The cards never teleport back to center.
      anims.push(board.animate([from,exit],{duration,easing:'cubic-bezier(.21,.7,.34,1)',fill:'both'}));
      anims.push(preview.animate([
        {...fromPreview,offset:0},
        {transform:`translate3d(${-sign*11}px,0,0) rotate(${-sign*.35}deg) scale(1.006)`,opacity:'1',offset:.88},
        {transform:'translate3d(0px,0,0) rotate(0deg) scale(1)',opacity:'1',offset:1}
      ],{duration:duration+75,easing:'cubic-bezier(.16,.9,.28,1)',fill:'both'}));
      S.animation={cancel(){anims.forEach(a=>a.cancel())}};
      await Promise.allSettled(anims.map(a=>a.finished));
    }
    if(S.page!=='compare'||!board.isConnected)return;
    // Replace only when the incoming view is fully on screen. The overlay stays visible over this swap.
    keepPassedProducts(oldIndex,to);
    board.innerHTML=pair(to);
    S.index=to;
    const nav=q('#cmpNav');if(nav)nav.innerHTML=navMarkup();
  }catch(error){
    // Never strand the user on an invisible card if an animation is interrupted.
    if(S.page==='compare'&&board.isConnected){keepPassedProducts(oldIndex,to);board.innerHTML=pair(to);S.index=to;const nav=q('#cmpNav');if(nav)nav.innerHTML=navMarkup()}
  }finally{
    anims.forEach(a=>{try{a.cancel()}catch(e){}});
    cleanSwipe(board,preview);
    S.animation=null;
    S.busy=false;
    q('.confirm-bar')?.remove();q('.confirm-spark')?.remove();
  }
}
async function snapSwipeBack(){
  const zone=q('#swipeZone'),board=q('#carousel');if(!zone||!board||S.busy)return;
  const preview=zone.querySelector('.swipe-preview');
  const width=swipeWidth(zone);
  const current=board.style.transform||swipePose(0,width).transform;
  const currentOpacity=board.style.opacity||'1';
  const previewStart=preview?.style.transform;
  S.busy=true;
  const animations=[];
  try{
    if(!prefersReducedMotion.matches){
      animations.push(board.animate([
        {transform:current,opacity:currentOpacity},
        {transform:'translate3d(0px,0,0) rotate(0deg) scale(1)',opacity:'1'}
      ],{duration:330,easing:'cubic-bezier(.18,.89,.22,1.06)',fill:'both'}));
      if(preview){
        const side=Number(preview.dataset.index)>S.index?1:-1;
        animations.push(preview.animate([
          {transform:previewStart||swipePose(side*width,width).transform,opacity:preview.style.opacity||'.9'},
          swipePose(side*width,width)
        ],{duration:300,easing:'cubic-bezier(.18,.89,.22,1.06)',fill:'both'}));
      }
      S.animation={cancel(){animations.forEach(a=>a.cancel())}};
      await Promise.allSettled(animations.map(a=>a.finished));
    }
  }finally{
    animations.forEach(a=>{try{a.cancel()}catch(e){}});
    cleanSwipe(board,preview);
    S.animation=null;
    S.busy=false;
  }
}
function attachSwipe(){
  const zone=q('#swipeZone'),board=q('#carousel');if(!zone||!board)return;
  let active=false,locked=false,pointerId=null,startX=0,startY=0,dx=0;
  let samples=[];
  zone.addEventListener('pointerdown',e=>{
    if(S.busy||S.sheet||e.target.closest('button')||(e.pointerType==='mouse'&&e.button!==0))return;
    active=true;locked=false;pointerId=e.pointerId;startX=e.clientX;startY=e.clientY;dx=0;
    samples=[{x:0,t:performance.now()}];
    try{zone.setPointerCapture(e.pointerId)}catch(_e){}
  });
  zone.addEventListener('pointermove',e=>{
    if(!active||e.pointerId!==pointerId||S.busy)return;
    const distance=e.clientX-startX,dy=e.clientY-startY;
    if(!locked&&Math.abs(dy)>Math.abs(distance)+6&&Math.abs(dy)>12){
      active=false;pointerId=null;snapSwipeBack();return;
    }
    if(!locked&&Math.abs(distance)<7)return;
    locked=true;dx=distance;
    const width=swipeWidth(zone);
    const direction=distance<0?1:-1;
    const to=S.index+direction;
    const isEdge=to<0||to>=products.length;
    const x=isEdge?Math.sign(distance)*Math.min(32,Math.abs(distance)*.15):Math.max(-width*.95,Math.min(width*.95,distance));
    zone.classList.add('swipe-active');
    setSwipePose(board,x,width);
    if(!isEdge){
      const preview=swipePreview(to);
      setSwipePose(preview,(direction*width)+x,width);
    }else zone.querySelector('.swipe-preview')?.remove();
    const time=performance.now();samples.push({x:distance,t:time});
    samples=samples.filter(p=>time-p.t<=135).slice(-9);
  });
  const end=(e,cancelled=false)=>{
    if(!active||(e&&e.pointerId!==pointerId))return;
    active=false;pointerId=null;
    if(!locked){dx=0;return}
    const width=swipeWidth(zone);
    const movement=dx;dx=0;
    const last=samples[samples.length-1],first=samples[0];
    const velocity=last&&first&&last.t!==first.t?(last.x-first.x)/(last.t-first.t):0;
    const direction=movement<0?1:-1;
    const next=S.index+direction;
    const valid=next>=0&&next<products.length;
    const commit=!cancelled&&valid&&(Math.abs(movement)>Math.min(68,width*.18)||(Math.abs(movement)>22&&Math.abs(velocity)>.42));
    if(commit)navigate(next,{dx:movement,velocity});
    else snapSwipeBack();
  };
  zone.addEventListener('pointerup',e=>end(e));
  zone.addEventListener('pointercancel',e=>end(e,true));
  zone.addEventListener('lostpointercapture',e=>{if(active)end(e,true)});
  let lastWheel=0;
  zone.addEventListener('wheel',e=>{
    if(S.busy||S.sheet||Math.abs(e.deltaX)<28||Math.abs(e.deltaX)<Math.abs(e.deltaY)*1.1)return;
    const now=performance.now();if(now-lastWheel<580)return;lastWheel=now;
    e.preventDefault();navigate(S.index+(e.deltaX>0?1:-1));
  },{passive:false});
}

function choose(which){if(S.page!=='compare'||S.busy||S.sheet)return;S.busy=true;const idx=S.index;S.choices[idx]=which;S.listFlash=idx;let board=q('#carousel');board.innerHTML=pair(idx);const card=q(`.offer-card.${which==='alt'?'alt':'not-existent'}`)||(which==='orig'?q('.offer-card'):null);if(card){card.animate([{transform:'scale(.985)'},{transform:'scale(1.018)'},{transform:'scale(1)'}],{duration:480,easing:'cubic-bezier(.18,1.5,.32,1)'})}q('#cmpNav').innerHTML=navMarkup();const banner=document.createElement('div');banner.className='confirm-bar';banner.innerHTML=`${ico('check',17,'white',2.8)} ${which==='alt'?'Je lijstje is aangepast':'Je huidige product is behouden'}`;q('.compare').appendChild(banner);let particles=document.createElement('div');particles.className='confirm-spark';particles.innerHTML=Array.from({length:8},(_,i)=>`<i style="--r:${i*45}deg;background:${i%2?'#00af97':'#f7a13c'}"></i>`).join('');q('.cmp-body').appendChild(particles);S.timer=setTimeout(()=>{if(S.page!=='compare')return;S.busy=false;const next=products.findIndex((p,j)=>j>idx&&S.choices[j]===null);const firstIncomplete=products.findIndex((p,j)=>S.choices[j]===null);if(next>=0)navigate(next);else if(firstIncomplete>=0)navigate(firstIncomplete);else summary()},1000)}
function allSheet(){if(S.page!=='compare'||S.sheet||S.busy)return;S.sheet='all';el.insertAdjacentHTML('beforeend',`<div class="modal-dim" data-action="close-modal"></div><section class="modal-sheet"><div class="modal-grip"></div><div class="modal-heading"><h2>Alle producten</h2><button data-action="close-modal" aria-label="Sluiten">${ico('close',22)}</button></div><p>Bekijk je keuzes of ga naar een ander product.</p>${products.map((p,i)=>`<button class="modal-item" data-action="select-product" data-index="${i}"><img src="${chosen(i).img}" alt=""><div><strong>${esc(chosen(i).name)}</strong><small>${S.choices[i]===null?'Nog geen keuze':S.choices[i]==='alt'?'Alternatief gekozen':'Product behouden'}</small></div><span class="${S.choices[i]!==null?'done':''}">${S.choices[i]!==null?ico('check',20):ico('right',18)}</span></button>`).join('')}<button class="modal-continue" data-action="close-modal">Verder kiezen</button></section>`)}
function closeModal(){if(S.sheet==='all'){q('.modal-dim')?.remove();q('.modal-sheet')?.remove()}else if(S.sheet==='hint'){q('.intro-mask')?.remove()}else if(S.sheet==='assistant'){q('.dim')?.remove();q('.assistant-sheet')?.remove();syncAssistantChrome(false)}S.sheet=null}
