function act(btn){const action=btn.dataset.action;switch(action){case'reset-demo':resetDemo();break;case'reset-menu':{const existing=el.querySelector('.hero-reset-menu');if(existing){existing.remove();break}const header=el.querySelector('.list-hero');if(header)header.insertAdjacentHTML('beforeend','<div class="hero-reset-menu"><button type="button" data-action="reset-demo">↻ &nbsp; Reset demo</button></div>');break}case'assistant':assistant();break;case'close-assistant':closeModal();break;case'start-scan':scan();break;case'close-hint':closeModal();break;case'keep':choose('orig');break;case'swap':choose('alt');break;case'jump':navigate(Number(btn.dataset.index));break;case'show-all':if(S.page==='compare'&&!S.sheet&&S.choices.some(v=>v!==null))summary();break;case'close-modal':closeModal();break;case'select-product':{const idx=Number(btn.dataset.index);closeModal();navigate(idx);break}case'leave':case'back-list':renderList();break;case'heart':btn.style.color=btn.style.color?'':'#f47b00';break;default:break}}
